from leann.api import SearchResult
from leann.metadata_filter import MetadataFilterEngine
from collections import defaultdict

def aggregate_search_results(
    search_results: List[SearchResult],
    group_by_field: str,
    aggregation_funcs: Optional[Dict[str, Callable]] = None
) -> Dict[str, Dict[str, Any]]:
    """Aggregate search results by a metadata field with optional statistics.

    Args:
        search_results: List of SearchResult objects to aggregate
        group_by_field: Metadata field name to group by
        aggregation_funcs: Optional dictionary mapping field_name to aggregation function.
            Example: {"score": max, "count": len}
            If None, defaults to count and average score per group

    Returns:
        Dictionary mapping group_value to aggregated statistics
        Example: {"tech": {"count": 5, "avg_score": 0.85, "max_score": 0.95}}
    """
    # Group search results by the specified metadata field
    grouped_results = defaultdict(list)

    for result in search_results:
        # Get the group value from metadata, default to 'unknown' if missing
        if hasattr(result, 'metadata') and result.metadata:
            group_value = result.metadata.get(group_by_field, 'unknown')
        else:
            group_value = 'unknown'

        # Convert group_value to string for consistent dictionary keys
        group_key = str(group_value)
        grouped_results[group_key].append(result)

    # Calculate aggregated statistics for each group
    aggregated_stats = {}

    for group_key, results in grouped_results.items():
        stats = {}

        if aggregation_funcs is None:
            # Default aggregation: count, average score, max score, min score
            stats['count'] = len(results)

            # Extract scores from results
            scores = [r.score for r in results if hasattr(r, 'score')]

            if scores:
                stats['avg_score'] = sum(scores) / len(scores)
                stats['max_score'] = max(scores)
                stats['min_score'] = min(scores)
            else:
                stats['avg_score'] = 0.0
                stats['max_score'] = 0.0
                stats['min_score'] = 0.0
        else:
            # Custom aggregation functions
            for stat_name, agg_func in aggregation_funcs.items():
                try:
                    if stat_name == 'count':
                        stats[stat_name] = agg_func(results)
                    elif stat_name == 'score' or 'score' in stat_name:
                        # Apply function to scores
                        scores = [r.score for r in results if hasattr(r, 'score')]
                        if scores:
                            stats[stat_name] = agg_func(scores)
                        else:
                            stats[stat_name] = None
                    else:
                        # Try to apply function to the results list
                        stats[stat_name] = agg_func(results)
                except Exception as e:
                    # If aggregation fails, set to None
                    stats[stat_name] = None

        aggregated_stats[group_key] = stats

    return aggregated_stats

